<template>
  <div>
    <page-title-bar title="文档解析与需求提取" subtitle="按章节查看规格原文与自动提取结果">
      <el-button type="primary" @click="$router.push('/test-points')">进入测试点提取</el-button>
    </page-title-bar>

    <el-row :gutter="16">
      <el-col :span="6">
        <el-card class="work-card section-tree-card">
          <div class="card-title">文档目录</div>
          <el-tree
            :data="treeData"
            node-key="id"
            :expand-on-click-node="false"
            :default-expanded-keys="[activeSection.id]"
            @node-click="changeSection"
          />
        </el-card>
      </el-col>

      <el-col :span="10">
        <el-card class="work-card">
          <div class="card-title">原文内容</div>
          <h3>{{ activeSection.label }}</h3>
          <p class="doc-content">{{ activeSection.content }}</p>
        </el-card>
      </el-col>

      <el-col :span="8">
        <el-card class="work-card">
          <div class="card-title">提取结果</div>
          <div class="result-block">
            <h4>功能点</h4>
            <el-tag v-for="item in activeSection.extract.functional" :key="item" type="success" effect="plain">
              {{ item }}
            </el-tag>
          </div>
          <div class="result-block">
            <h4>边界点</h4>
            <el-tag v-for="item in activeSection.extract.boundary" :key="item" type="warning" effect="plain">
              {{ item }}
            </el-tag>
          </div>
          <div class="result-block">
            <h4>异常点</h4>
            <el-tag v-for="item in activeSection.extract.exception" :key="item" type="danger" effect="plain">
              {{ item }}
            </el-tag>
          </div>
          <div class="result-block">
            <h4>恢复点</h4>
            <el-tag v-for="item in activeSection.extract.recovery" :key="item" type="info" effect="plain">
              {{ item }}
            </el-tag>
          </div>
        </el-card>
      </el-col>
    </el-row>
  </div>
</template>

<script>
import PageTitleBar from "../components/PageTitleBar.vue";
import { useWorkspaceStore } from "../mock/workspaceStore";

export default {
  name: "DocumentParseView",
  components: { PageTitleBar },
  data() {
    const store = useWorkspaceStore();
    return {
      store,
    };
  },
  computed: {
    treeData() {
      return this.store.documentSections.map((item) => ({
        id: item.id,
        label: item.label,
      }));
    },
    activeSection() {
      return (
        this.store.documentSections.find((item) => item.id === this.store.state.currentSectionId) ||
        this.store.documentSections[0]
      );
    },
  },
  created() {
    if (!this.store.state.documentLoaded) {
      this.$message.info("请先导入示例文档。");
      this.$router.replace("/import");
    }
  },
  methods: {
    changeSection(node) {
      this.store.state.currentSectionId = node.id;
    },
  },
};
</script>

