<template>
  <div>
    <page-title-bar title="测试点提取与确认" subtitle="筛选并确认需要生成测试用例的测试点">
      <el-button @click="resetSelection">清空选择</el-button>
      <el-button type="primary" :disabled="!selectedIds.length" @click="goNext">
        进入测试用例生成（{{ selectedIds.length }}）
      </el-button>
    </page-title-bar>

    <el-card class="work-card">
      <el-row :gutter="12" class="toolbar">
        <el-col :span="8">
          <el-input v-model="keyword" clearable placeholder="搜索测试点标题 / 标签" />
        </el-col>
        <el-col :span="6">
          <el-select v-model="typeFilter" clearable placeholder="按类型筛选" style="width: 100%">
            <el-option label="功能点" value="功能点" />
            <el-option label="边界点" value="边界点" />
            <el-option label="异常点" value="异常点" />
            <el-option label="恢复点" value="恢复点" />
          </el-select>
        </el-col>
        <el-col :span="10" class="right-action">
          <el-tag type="info">总计 {{ filteredList.length }} 条</el-tag>
        </el-col>
      </el-row>

      <el-table :data="filteredList" border @selection-change="onSelectionChange">
        <el-table-column type="selection" width="55" />
        <el-table-column prop="id" label="编号" width="100" />
        <el-table-column prop="title" label="测试点" min-width="280" />
        <el-table-column prop="type" label="类型" width="90" />
        <el-table-column prop="priority" label="优先级" width="90" />
        <el-table-column label="标签" width="180">
          <template slot-scope="{ row }">
            <el-tag v-for="tag in row.tags" :key="tag" size="mini" effect="plain">{{ tag }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column label="操作" width="140">
          <template slot-scope="{ row }">
            <el-button type="text" @click="showDetail(row)">查看详情</el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <el-drawer :visible.sync="drawerVisible" size="40%" title="测试点详情">
      <template v-if="activePoint">
        <el-descriptions :column="1" border>
          <el-descriptions-item label="测试点">{{ activePoint.title }}</el-descriptions-item>
          <el-descriptions-item label="来源原文">{{ activePoint.sourceText }}</el-descriptions-item>
          <el-descriptions-item label="提取原因">{{ activePoint.reason }}</el-descriptions-item>
          <el-descriptions-item label="建议扩展维度">{{ activePoint.expansion }}</el-descriptions-item>
        </el-descriptions>
      </template>
    </el-drawer>
  </div>
</template>

<script>
import PageTitleBar from "../components/PageTitleBar.vue";
import { useWorkspaceStore } from "../mock/workspaceStore";

export default {
  name: "TestPointExtractionView",
  components: { PageTitleBar },
  data() {
    const store = useWorkspaceStore();
    return {
      store,
      keyword: "",
      typeFilter: "",
      drawerVisible: false,
      activePoint: null,
      selectedIds: [...store.state.selectedPointIds],
    };
  },
  computed: {
    filteredList() {
      return this.store.testPoints.filter((item) => {
        const matchType = this.typeFilter ? item.type === this.typeFilter : true;
        const text = `${item.title}|${item.tags.join("|")}`;
        const matchKeyword = this.keyword ? text.includes(this.keyword) : true;
        return matchType && matchKeyword;
      });
    },
  },
  methods: {
    showDetail(row) {
      this.activePoint = row;
      this.drawerVisible = true;
    },
    onSelectionChange(rows) {
      this.selectedIds = rows.map((item) => item.id);
      this.store.state.selectedPointIds = [...this.selectedIds];
    },
    resetSelection() {
      this.selectedIds = [];
      this.store.state.selectedPointIds = [];
      this.$message.success("已清空测试点选择。");
    },
    goNext() {
      this.store.state.selectedPointIds = [...this.selectedIds];
      this.$router.push("/case-generation");
    },
  },
};
</script>

<style scoped>
.work-card {
  border: 1px solid #d8e4f4;
}

.toolbar {
  margin-bottom: 14px;
}

.right-action {
  display: flex;
  justify-content: flex-end;
  align-items: center;
}

.el-tag {
  margin-right: 6px;
}
</style>
