<template>
  <div>
    <page-title-bar title="文档导入" subtitle="导入芯片规格文档并启动解析流程">
      <el-button @click="loadSample">载入示例文档</el-button>
      <el-button type="primary" :disabled="!store.state.documentLoaded" @click="startParsing">开始解析</el-button>
    </page-title-bar>

    <el-card class="panel-card">
      <el-upload
        drag
        action="#"
        :auto-upload="false"
        :show-file-list="false"
        :on-change="onSelectFile"
        class="upload-zone"
      >
        <i class="el-icon-upload"></i>
        <div class="el-upload__text">将规格文档拖拽至此，或点击选择文件</div>
        <div class="el-upload__tip">原型模式下仅模拟上传，不会连接后端。</div>
      </el-upload>
    </el-card>

    <el-card class="panel-card">
      <div class="card-title">文档信息</div>
      <el-descriptions :column="3" border>
        <el-descriptions-item label="文档名称">{{ currentMeta.name }}</el-descriptions-item>
        <el-descriptions-item label="版本">{{ currentMeta.version }}</el-descriptions-item>
        <el-descriptions-item label="模块">{{ currentMeta.module }}</el-descriptions-item>
        <el-descriptions-item label="上传时间">{{ currentMeta.uploadTime }}</el-descriptions-item>
        <el-descriptions-item label="状态">
          <el-tag :type="store.state.documentLoaded ? 'success' : 'info'">{{ currentMeta.status }}</el-tag>
        </el-descriptions-item>
      </el-descriptions>
    </el-card>
  </div>
</template>

<script>
import PageTitleBar from "../components/PageTitleBar.vue";
import { useWorkspaceStore } from "../mock/workspaceStore";

export default {
  name: "DocumentImportView",
  components: { PageTitleBar },
  data() {
    const store = useWorkspaceStore();
    return {
      store,
      localMeta: null,
    };
  },
  computed: {
    currentMeta() {
      if (this.localMeta) {
        return this.localMeta;
      }
      const base = this.store.documentMeta;
      return {
        ...base,
        status: this.store.state.documentLoaded ? "已载入" : "待导入",
      };
    },
  },
  methods: {
    loadSample() {
      this.store.state.documentLoaded = true;
      this.localMeta = {
        ...this.store.documentMeta,
        status: "已载入",
      };
      this.$message.success("示例文档已载入，可开始解析。");
    },
    onSelectFile(file) {
      this.store.state.documentLoaded = true;
      this.localMeta = {
        ...this.store.documentMeta,
        name: file.name,
        uploadTime: "2026-03-09 10:35",
        status: "已载入（本地模拟）",
      };
      this.$message.success("文件已加入队列（本地模拟上传）。");
    },
    startParsing() {
      this.store.state.parsingStarted = true;
      this.$message.success("解析任务已启动，进入文档解析页。");
      this.$router.push("/parse");
    },
  },
};
</script>

<style scoped>
.panel-card {
  margin-bottom: 16px;
  border: 1px solid #d8e4f4;
}

.upload-zone {
  width: 100%;
}

.card-title {
  margin-bottom: 14px;
  font-size: 15px;
  color: #20365f;
  font-weight: 600;
}
</style>
