  name: "WorkflowSidebar",
  computed: {
    activePath() {
      return this.$route.path;
    },
  },
  methods: {
    onSelect(path) {
      if (path === this.$route.path) {
        return;
      }
      this.$router.push(path).catch((err) => {
        if (!err || err.name === "NavigationDuplicated") {
          return;
        }
        throw err;
      });
    },
  },
};
