import Vue from "vue";
import { documentMeta, documentSections, testPoints, testCases, caseCodes } from "./dpuData";

const state = Vue.observable({
  documentLoaded: false,
  parsingStarted: false,
  currentSectionId: documentSections[0].id,
  selectedPointIds: [],
  selectedCaseId: testCases[0].id,
  caseStatuses: testCases.reduce((map, item) => {
    map[item.id] = item.status;
    return map;
  }, {}),
});

export function useWorkspaceStore() {
  const selectedPoints = () => testPoints.filter((item) => state.selectedPointIds.includes(item.id));

  const filteredCases = () => {
    if (!state.selectedPointIds.length) {
      return testCases;
    }
    return testCases.filter((item) => state.selectedPointIds.includes(item.pointId));
  };

  return {
    state,
    documentMeta,
    documentSections,
    testPoints,
    testCases,
    caseCodes,
    selectedPoints,
    filteredCases,
  };
}
