          ],
        },
        {
          id: "02",
          nav: "项目需求",
          title: "项目需求：构建端到端测试智能生产线",
          desc: "把“文档理解-测试点生成-用例构建-代码落地”串成一个可演进的流程系统。",
          theme: "theme-need",
          metricLabel: "目标交付模式",
          metricValue: "E2E",
          metricNote: "把测试设计、评审、代码生成与知识反馈放进同一条生产链",
          metrics: [
            { label: "链路阶段", value: "4段" },
            { label: "输出形态", value: "结构化" },
          ],
          flowTitle: "需求闭环",
          stages: ["文档理解", "测试点抽取", "用例构建", "代码落地"],
          tags: ["端到端", "结构化", "工程化流转"],
          points: [
            "支持从规格文档自动抽取需求与约束",
            "建立功能/边界/异常/恢复四类测试模型",
            "输出标准化测试用例，支持评审流转",
            "自动生成可执行代码并保留补全提示",
          ],
        },
        {
          id: "03",
          nav: "项目功能",
          title: "项目功能：大模型 + 规则引擎协同生成",
          desc: "通过自训练大模型和规则引擎共治，兼顾生成能力、专业准确性和可审计性。",
