            "知识沉淀：自动回灌测试经验，形成组织级测试知识库",
          ],
        },
        {
          id: "04",
          nav: "项目架构",
          title: "项目架构：从数据到执行的闭环平台",
          desc: "以模块化架构组织能力层，形成可扩展、可部署、可持续优化的测试智能底座。",
          theme: "theme-arch",
          metricLabel: "平台分层",
          metricValue: "4 Layer",
          metricNote: "从数据、模型、引擎到应用逐层解耦，支撑长期演进与多项目复用",
          metrics: [
            { label: "能力模块", value: "可扩展" },
            { label: "反馈闭环", value: "持续优化" },
          ],
          flowTitle: "平台拓扑",
          stages: ["数据层", "模型层", "引擎层", "应用层"],
          tags: ["模块化架构", "检索增强", "质量闭环"],
          points: [
            "数据层：规格文档、接口定义、历史用例、缺陷记录",
            "模型层：领域大模型、RAG 检索、提示编排",
            "引擎层：规则校验、模板生成、代码合成",
            "应用层：工作台编排、结果导出、质量看板与反馈闭环",
          ],
        },
      ],
    };
  },
  computed: {
    activeScene() {
      return this.scenes[this.activeSceneIndex] || this.scenes[0];
    },
    navStyle() {
      if (this.navMode === "fixed") {
        return {
          left: `${this.navLeft}px`,
          width: `${this.navWidth}px`,
          top: `${this.navTop}px`,
        };
      }
      if (this.navMode === "bottom") {
        return {
          width: `${this.navWidth}px`,
        };
      }
      return {};
    },
  },
  mounted() {
    this.scrollHost = this.$el.parentElement;
    if (this.scrollHost) {
      this.scrollHost.addEventListener("scroll", this.onScroll, { passive: true });
    }
    window.addEventListener("resize", this.onResize, { passive: true });
    this.$nextTick(() => {
      this.initSceneObserver();
      this.updateNavPosition();
    });
  },
  beforeDestroy() {
    if (this.sceneObserver) {
      this.sceneObserver.disconnect();
      this.sceneObserver = null;
    }
    if (this.scrollHost) {
      this.scrollHost.removeEventListener("scroll", this.onScroll);
    }
    window.removeEventListener("resize", this.onResize);
    if (this.rafId) {
      cancelAnimationFrame(this.rafId);
    }
  },
  methods: {
    goWorkbench() {
      this.$router.push("/workbench");
    },
    jumpToScene(index) {
      const items = this.$refs.sceneItems || [];
      const target = items[index];
      if (target && target.scrollIntoView) {
        target.scrollIntoView({ behavior: "smooth", block: "center" });
      }
    },
    initSceneObserver() {
      const items = this.$refs.sceneItems || [];
      if (!items.length) return;

      if (!window.IntersectionObserver) {
        this.activeSceneIndex = 0;
        return;
      }

      this.sceneObserver = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (!entry.isIntersecting) return;
            const idx = Number(entry.target.getAttribute("data-scene-index"));
            if (!Number.isNaN(idx)) {
              this.activeSceneIndex = idx;
            }
          });
        },
        {
          root: this.scrollHost || null,
          rootMargin: "-20% 0px -45% 0px",
          threshold: 0.3,
        }
      );

      items.forEach((item) => this.sceneObserver.observe(item));
    },
    onResize() {
      this.updateNavPosition();
    },
    onScroll() {
      if (this.rafId) {
        cancelAnimationFrame(this.rafId);
      }
      this.rafId = requestAnimationFrame(() => {
        this.updateNavPosition();
      });
    },
    updateNavPosition() {
      const shell = this.$refs.storyShell;
      const nav = this.$refs.storyNav;
      const navSticky = this.$refs.navSticky;
      if (!shell || !nav || !navSticky) return;

      if (window.innerWidth <= 1080) {
        this.navMode = "static";
        return;
      }

      const topOffset = this.navTop;
      const shellRect = shell.getBoundingClientRect();
      const navRect = navSticky.getBoundingClientRect();
      const navHeight = navRect.height;

      this.navLeft = shellRect.left;
      this.navWidth = nav.getBoundingClientRect().width;

      if (shellRect.top > topOffset) {
        this.navMode = "static";
        return;
      }

      if (shellRect.bottom <= topOffset + navHeight + 8) {
        this.navMode = "bottom";
        return;
      }

      this.navMode = "fixed";
    },
  },
};
</script>

