<template>
  <div>
    <page-title-bar title="测试用例生成" subtitle="基于已确认测试点生成测试用例并进行评审处理">
      <el-button @click="$router.push('/test-points')">返回测试点页</el-button>
      <el-button type="primary" @click="$router.push('/code-generation')">进入代码生成</el-button>
    </page-title-bar>

    <el-row :gutter="16">
      <el-col :span="5">
        <el-card class="work-card side-card">
          <div class="card-title">已选测试点</div>
          <el-empty v-if="!selectedPoints.length" description="尚未选择测试点" :image-size="70" />
          <el-timeline v-else>
            <el-timeline-item v-for="item in selectedPoints" :key="item.id" :timestamp="item.id" placement="top">
              {{ item.title }}
            </el-timeline-item>
          </el-timeline>
        </el-card>
      </el-col>

      <el-col :span="9">
        <el-card class="work-card">
          <div class="card-title">生成用例列表</div>
          <el-table :data="caseList" border highlight-current-row @current-change="changeCase" row-key="id">
            <el-table-column prop="id" label="编号" width="95" />
            <el-table-column prop="title" label="标题" min-width="220" />
            <el-table-column label="状态" width="120">
              <template slot-scope="{ row }">
                <el-tag :type="statusType(getStatus(row.id))">{{ getStatus(row.id) }}</el-tag>
              </template>
            </el-table-column>
          </el-table>
        </el-card>
      </el-col>

      <el-col :span="10">
        <el-card class="work-card">
          <div class="card-title">用例详情</div>
          <template v-if="activeCase">
            <el-descriptions :column="1" border>
              <el-descriptions-item label="标题">{{ activeCase.title }}</el-descriptions-item>
              <el-descriptions-item label="前置条件">{{ activeCase.preconditions.join("；") }}</el-descriptions-item>
              <el-descriptions-item label="测试步骤">{{ activeCase.steps.join("；") }}</el-descriptions-item>
              <el-descriptions-item label="预期结果">{{ activeCase.expected.join("；") }}</el-descriptions-item>
              <el-descriptions-item label="关联需求">{{ activeCase.requirement }}</el-descriptions-item>
              <el-descriptions-item label="生成依据">{{ activeCase.basis }}</el-descriptions-item>
            </el-descriptions>
            <div class="btn-row">
              <el-button type="success" @click="setStatus('已接受')">接受</el-button>
              <el-button @click="openEdit">编辑</el-button>
              <el-button type="danger" plain @click="setStatus('已驳回')">驳回</el-button>
              <el-button type="primary" plain @click="goCode">生成代码</el-button>
            </div>
          </template>
        </el-card>
      </el-col>
    </el-row>

    <el-dialog title="编辑测试用例" :visible.sync="editVisible" width="50%">
      <el-form v-if="editModel" label-width="90px">
        <el-form-item label="标题">
          <el-input v-model="editModel.title" />
        </el-form-item>
        <el-form-item label="测试步骤">
          <el-input type="textarea" :rows="4" v-model="stepText" />
        </el-form-item>
        <el-form-item label="预期结果">
          <el-input type="textarea" :rows="4" v-model="expectedText" />
        </el-form-item>
      </el-form>
      <span slot="footer">
        <el-button @click="editVisible = false">取消</el-button>
        <el-button type="primary" @click="saveEdit">保存</el-button>
      </span>
    </el-dialog>
  </div>
</template>

<script>
import PageTitleBar from "../components/PageTitleBar.vue";
import { useWorkspaceStore } from "../mock/workspaceStore";

export default {
  name: "CaseGenerationView",
  components: { PageTitleBar },
  data() {
    const store = useWorkspaceStore();
    return {
      store,
      editVisible: false,
      editModel: null,
      stepText: "",
      expectedText: "",
    };
  },
  computed: {
    selectedPoints() {
      return this.store.selectedPoints();
    },
    caseList() {
      return this.store.filteredCases();
    },
    activeCase() {
      return this.caseList.find((item) => item.id === this.store.state.selectedCaseId) || this.caseList[0];
    },
  },
  watch: {
    caseList: {
      immediate: true,
      handler(list) {
        if (!list.length) return;
        if (!list.find((item) => item.id === this.store.state.selectedCaseId)) {
          this.store.state.selectedCaseId = list[0].id;
        }
      },
    },
  },
  methods: {
    statusType(status) {
      if (status === "已接受") return "success";
      if (status === "已驳回") return "danger";
      return "info";
    },
    getStatus(caseId) {
      return this.store.state.caseStatuses[caseId] || "待确认";
    },
    changeCase(row) {
      if (row) {
        this.store.state.selectedCaseId = row.id;
      }
    },
    setStatus(value) {
      if (!this.activeCase) return;
      this.$set(this.store.state.caseStatuses, this.activeCase.id, value);
      this.$message.success(`用例 ${this.activeCase.id} 状态已更新为${value}`);
    },
    openEdit() {
      if (!this.activeCase) return;
      this.editModel = { ...this.activeCase };
      this.stepText = this.editModel.steps.join("\n");
      this.expectedText = this.editModel.expected.join("\n");
      this.editVisible = true;
    },
    saveEdit() {
      const target = this.store.testCases.find((item) => item.id === this.editModel.id);
      if (target) {
        target.title = this.editModel.title;
        target.steps = this.stepText.split("\n").filter(Boolean);
        target.expected = this.expectedText.split("\n").filter(Boolean);
      }
      this.editVisible = false;
      this.$message.success("用例内容已更新。");
    },
    goCode() {
      if (this.activeCase) {
        this.store.state.selectedCaseId = this.activeCase.id;
      }
      this.$router.push("/code-generation");
    },
  },
};
</script>

