import Vue from "vue";
import Router from "vue-router";
import Landing from "../views/Landing.vue";
import Dashboard from "../views/Dashboard.vue";
import DocumentImport from "../views/DocumentImport.vue";
import DocumentParse from "../views/DocumentParse.vue";
import TestPointExtraction from "../views/TestPointExtraction.vue";
import CaseGeneration from "../views/CaseGeneration.vue";
import CodeGeneration from "../views/CodeGeneration.vue";

Vue.use(Router);

const router = new Router({
  mode: "hash",
  routes: [
    { path: "/", name: "landing", component: Landing, meta: { title: "Chipilot AI", layout: "landing" } },
    { path: "/workbench", redirect: "/dashboard" },
    { path: "/dashboard", name: "dashboard", component: Dashboard, meta: { title: "Dashboard" } },
    { path: "/import", name: "import", component: DocumentImport, meta: { title: "Document Import" } },
    { path: "/parse", name: "parse", component: DocumentParse, meta: { title: "Document Parse" } },
    { path: "/test-points", name: "test-points", component: TestPointExtraction, meta: { title: "Test Points" } },
    {
      path: "/case-generation",
      name: "case-generation",
      component: CaseGeneration,
      meta: { title: "Case Generation" },
    },
    {
      path: "/code-generation",
      name: "code-generation",
      component: CodeGeneration,
      meta: { title: "Code Generation" },
    },
  ],
});

router.afterEach((to) => {
  document.title = `${to.meta.title || "Chipilot"} - Chipilot`;
});

export default router;
