<template>
  <div>
    <page-title-bar title="测试用例代码生成" subtitle="查看生成代码、依赖接口与待补全项，并执行导出模拟">
      <el-button @click="$router.push('/case-generation')">返回用例页</el-button>
      <el-button type="primary" @click="exportAll">导出结果</el-button>
    </page-title-bar>

    <el-row :gutter="16">
      <el-col :span="6">
        <el-card class="work-card">
          <div class="card-title">测试用例摘要</div>
          <el-menu :default-active="activeCode.id" @select="pickCode">
            <el-menu-item v-for="item in codeList" :key="item.id" :index="item.id">
              <div class="menu-title">{{ item.id }}</div>
              <div class="menu-sub">{{ caseTitle(item.id) }}</div>
            </el-menu-item>
          </el-menu>
        </el-card>
      </el-col>

      <el-col :span="18">
        <el-card class="work-card">
          <div class="card-title">生成代码（{{ activeCode.language }}）</div>
          <pre class="code-box">{{ activeCode.code }}</pre>
          <div class="btn-row">
            <el-button @click="copyCode">复制代码</el-button>
            <el-button type="primary" plain @click="exportPy">导出 .py</el-button>
          </div>
        </el-card>

        <el-card class="work-card bottom-card">
          <div class="card-title">依赖接口与待补全项</div>
          <el-row :gutter="16">
            <el-col :span="12">
              <h4>依赖接口</h4>
              <el-tag v-for="dep in activeCode.dependencies" :key="dep" effect="plain" type="info">{{ dep }}</el-tag>
            </el-col>
            <el-col :span="12">
              <h4>待补全项</h4>
              <el-alert
                v-for="todo in activeCode.todos"
                :key="todo"
                :title="todo"
                type="warning"
                :closable="false"
                show-icon
              />
            </el-col>
          </el-row>
        </el-card>
      </el-col>
    </el-row>
  </div>
</template>

<script>
import PageTitleBar from "../components/PageTitleBar.vue";
import { useWorkspaceStore } from "../mock/workspaceStore";

export default {
  name: "CodeGenerationView",
  components: { PageTitleBar },
  data() {
    const store = useWorkspaceStore();
    const defaultCode = store.caseCodes.find((item) => item.id === store.state.selectedCaseId) || store.caseCodes[0];
    return {
      store,
      activeCodeId: defaultCode.id,
    };
  },
  computed: {
    codeList() {
      const filtered = this.store.filteredCases().map((item) => item.id);
      const list = this.store.caseCodes.filter((item) => filtered.includes(item.id));
      return list.length ? list : this.store.caseCodes;
    },
    activeCode() {
      return this.codeList.find((item) => item.id === this.activeCodeId) || this.codeList[0];
    },
  },
  methods: {
    caseTitle(caseId) {
      const target = this.store.testCases.find((item) => item.id === caseId);
      return target ? target.title : "未知用例";
    },
    pickCode(caseId) {
      this.activeCodeId = caseId;
      this.store.state.selectedCaseId = caseId;
    },
    copyCode() {
      if (!navigator.clipboard) {
        this.$message.warning("当前环境不支持剪贴板 API。");
        return;
      }
      navigator.clipboard.writeText(this.activeCode.code).then(() => {
        this.$message.success("代码已复制到剪贴板。");
      });
    },
    exportPy() {
      const blob = new Blob([this.activeCode.code], { type: "text/x-python" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `${this.activeCode.id}.py`;
      link.click();
      URL.revokeObjectURL(link.href);
      this.$message.success("已模拟导出 .py 文件。");
    },
    exportAll() {
      this.$confirm("确认导出测试点、用例与代码结果（模拟）？", "导出结果", { type: "warning" })
        .then(() => {
          this.$message.success("导出任务已提交（前端模拟）。");
        })
        .catch(() => {});
    },
  },
};
</script>

